RESERVED = ('job_in_flight', 'converted_org', 'session_revoked')
REFUSAL_FAMILY = ('client', 'admin', 'config', 'onboarding', 'origin', 'issues', 'org', 'dashboard', 'credits', 'label-map', 'fde', 'campaigns')


def layers(row):
    """a row's layers as a tuple"""
    return row[2] if isinstance(row[2], tuple) else (row[2],)


def statuses(row):
    """a row's statuses as a tuple, empty for None"""
    s = row[1]
    return () if s is None else (s if isinstance(s, tuple) else (s,))


def page_codes():
    """the codes a conductor answer may carry, every layer but the box alone, then the reserved names"""
    return tuple(r[0] for r in CODES if set(layers(r)) - {'box'}) + RESERVED


def box_refusals():
    """the box's coded refusals, the rows with a status"""
    return tuple(r[0] for r in CODES if 'box' in layers(r) and statuses(r))


def box_diagnostics():
    """the box's job-state and prune words, the rows without a status"""
    return tuple(r[0] for r in CODES if 'box' in layers(r) and not statuses(r))
